function validate([grid, pattern]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 1000) return 'Each row needs 1 to 1000 cells.';
  if (grid.length * n > 100000) return 'grid has at most 10^5 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(ch => typeof ch !== 'string' || !/^[a-z]$/.test(ch))) return 'Each cell is one lowercase letter.';
  }
  if (typeof pattern !== 'string' || !/^[a-z]+$/.test(pattern)) return 'pattern is one or more lowercase letters.';
  if (pattern.length > grid.length * n) return 'pattern is at most m * n letters long.';
  return null;
}

