function countCells(grid, pattern) {
  const m = grid.length;
  const n = grid[0].length;
  const len = pattern.length;
  const lps = new Array(len).fill(0);
  let border = 0;
  for (let i = 1; i < len; i++) {
    while (border > 0 && pattern[i] !== pattern[border]) border = lps[border - 1];
    if (pattern[i] === pattern[border]) border++;
    lps[i] = border;
  }

  function coverage(text) {
    const diff = new Array(text.length + 1).fill(0);
    let matched = 0;
    for (let i = 0; i < text.length; i++) {
      while (matched > 0 && text[i] !== pattern[matched]) matched = lps[matched - 1];
      if (text[i] === pattern[matched]) matched++;
      if (matched === len) {
        diff[i - len + 1]++;
        diff[i + 1]--;
        matched = lps[matched - 1];
      }
    }
    const covered = new Array(text.length).fill(false);
    let active = 0;
    for (let i = 0; i < text.length; i++) {
      active += diff[i];
      covered[i] = active > 0;
    }
    return covered;
  }

  let rowText = '';
  for (let r = 0; r < m; r++) rowText += grid[r].join('');
  let colText = '';
  for (let c = 0; c < n; c++) {
    for (let r = 0; r < m; r++) colText += grid[r][c];
  }
  const inRow = coverage(rowText);
  const inCol = coverage(colText);
  let count = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (inRow[r * n + c] && inCol[c * m + r]) count++;
    }
  }
  return count;
}

