function countCells(grid, pattern) {
  const m = grid.length, n = grid[0].length, total = m * n, len = pattern.length;
  const horizontal = new Set(), vertical = new Set();
  // Try every start position in both readings and compare letter by letter through the grid.
  for (let start = 0; start + len <= total; start++) {
    let rowOk = true, colOk = true;
    for (let t = 0; t < len; t++) {
      const p = start + t;
      if (grid[Math.floor(p / n)][p % n] !== pattern[t]) rowOk = false;
      if (grid[p % m][Math.floor(p / m)] !== pattern[t]) colOk = false;
    }
    for (let t = 0; t < len; t++) {
      const p = start + t;
      if (rowOk) horizontal.add(`${Math.floor(p / n)},${p % n}`);
      if (colOk) vertical.add(`${p % m},${Math.floor(p / m)}`);
    }
  }
  let count = 0;
  for (const cell of horizontal) if (vertical.has(cell)) count++;
  return count;
}

