function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? int(50, 100) : int(1, 5);
  const n = large ? int(50, 100) : int(1, 5);
  const total = m * n;
  const mode = rand();
  let grid;
  if (mode < 0.15) {
    // One letter everywhere: every cell is covered whenever the pattern fits.
    grid = Array.from({ length: m }, () => Array(n).fill('a'));
    return [grid, 'a'.repeat(int(1, Math.min(total, large ? 300 : 6)))];
  }
  if (mode < 0.35) {
    // A short word repeated along the rows makes long periodic matches.
    const word = Array.from({ length: int(1, 3) }, () => letters[int(0, 1)]).join('');
    grid = Array.from({ length: m }, (_, r) => Array.from({ length: n }, (_, c) => word[(r * n + c) % word.length]));
  } else {
    const k = large ? int(2, 3) : int(1, 3);
    grid = Array.from({ length: m }, () => Array.from({ length: n }, () => letters[int(0, k - 1)]));
  }
  const len = int(1, Math.min(total, large ? 7 : 5));
  const pick = rand();
  let text = '';
  if (pick < 0.4) for (const row of grid) text += row.join('');
  else if (pick < 0.8) for (let c = 0; c < n; c++) for (let r = 0; r < m; r++) text += grid[r][c];
  else text = Array.from({ length: len }, () => letters[int(0, 2)]).join('');
  const start = int(0, text.length - len);
  return [grid, text.slice(start, start + len)];
}
